static const char scene_skybox_frag_glsl[] =
    "#version 410\n"
    "#define GENESIS_GLSL 1\n"
    "/*\n"
    " * Genesis Render - skybox / environment background\n"
    " *\n"
    " * Drawn as a fullscreen quad at the far plane (depth test LEQUAL, depth write\n"
    " * off, or depth forced to 1.0) after the opaque geometry.  The world ray is\n"
    " * reconstructed from the inverse view-projection matrix so that the skybox\n"
    " * automatically respects the per-backend clip space conventions.\n"
    " *\n"
    " * Modes (u_env_params.w and the bound textures):\n"
    " *   0 - procedural gradient sky (u_sky_tint / u_ground_tint + sun disc)\n"
    " *   1 - equirectangular HDR map  (u_src_equirect bound at set 0 binding 1)\n"
    " *   2 - prefiltered cubemap      (u_prefilter_map bound at set 0 binding 4)\n"
    " */\n"
    "// ---- begin common/genesis_shader.h ----\n"
    "/*\n"
    " * Genesis Render - GLSL dialect header\n"
    " *\n"
    " * One GLSL source is authored for both backends.  scripts/build_shaders.py\n"
    " * prepends `#version` and defines exactly one of GENESIS_VK / GENESIS_GLSL\n"
    " * before inlining this header.\n"
    " *\n"
    " *   Vulkan : GLSL 450, explicit set/binding qualifiers, push constants.\n"
    " *   OpenGL : GLSL 410 (the macOS ceiling), no binding qualifiers.  The GL RHI\n"
    " *            backend binds uniform blocks by NAME to the deterministic index\n"
    " *            glUniformBlockIndex(set, binding) and assigns sampler units with\n"
    " *            glTextureUnit(set, binding) via glUniform1i at pipeline build time.\n"
    " *            Push constants are emulated by a std140 block named exactly\n"
    " *            `PushConstants` bound to uniform block index 0.\n"
    " *\n"
    " * Binding budget (kept inside the GL 4.1 minimum limits:\n"
    " * GL_MAX_UNIFORM_BUFFER_BINDINGS >= 36, GL_MAX_TEXTURE_IMAGE_UNITS >= 16):\n"
    " *\n"
    " *   set 0 (scene, bound once per frame)\n"
    " *     binding 0 : UBO   PerFrame          -> GL block 1\n"
    " *     binding 1 : UBO   Lights            -> GL block 2\n"
    " *     binding 2 : UBO   Environment       -> GL block 3\n"
    " *     binding 3 : cube  u_irradiance_map  -> GL unit 3\n"
    " *     binding 4 : cube  u_prefilter_map   -> GL unit 4\n"
    " *     binding 5 : 2D    u_brdf_lut        -> GL unit 5\n"
    " *   set 1 (material, bound per draw)\n"
    " *     binding 0 : UBO   Material          -> GL block 9\n"
    " *     binding 1 : 2D    u_base_color      -> GL unit 9\n"
    " *     binding 2 : 2D    u_metallic_roughness -> GL unit 10\n"
    " *     binding 3 : 2D    u_normal          -> GL unit 11\n"
    " *     binding 4 : 2D    u_occlusion       -> GL unit 12\n"
    " *     binding 5 : 2D    u_emissive        -> GL unit 13\n"
    " *   set 2 (per draw, dynamic offset)\n"
    " *     binding 0 : UBO   PerDraw           -> GL block 17\n"
    " */\n"
    "#ifndef GENESIS_SHADER_COMMON_H\n"
    "#define GENESIS_SHADER_COMMON_H\n"
    "\n"
    "// NOTE: macro parameter names must NOT collide with GLSL layout qualifier\n"
    "// keywords (`set`, `binding`, `location`), otherwise the preprocessor replaces\n"
    "// the keyword too and produces `layout(location = 0)` -> `layout(0 = 0)`.\n"
    "#ifdef GENESIS_VK\n"
    "#define GS_UBO(gs_set, gs_binding, gs_block) layout(set = gs_set, binding = gs_binding, std140) uniform gs_block\n"
    "#define GS_TEX2D(gs_set, gs_binding, gs_name) layout(set = gs_set, binding = gs_binding) uniform sampler2D gs_name\n"
    "#define GS_TEXCUBE(gs_set, gs_binding, gs_name) layout(set = gs_set, binding = gs_binding) uniform samplerCube gs_name\n"
    "#define GS_TEX2D_ARRAY(gs_set, gs_binding, gs_name) layout(set = gs_set, binding = gs_binding) uniform sampler2DArray gs_name\n"
    "#define GS_PUSH(gs_block) layout(push_constant) uniform gs_block\n"
    "#define GS_IN(gs_loc, gs_type, gs_name) layout(location = gs_loc) in gs_type gs_name\n"
    "#define GS_OUT(gs_loc, gs_type, gs_name) layout(location = gs_loc) out gs_type gs_name\n"
    "#else\n"
    "#define GS_UBO(gs_set, gs_binding, gs_block) layout(std140) uniform gs_block\n"
    "#define GS_TEX2D(gs_set, gs_binding, gs_name) uniform sampler2D gs_name\n"
    "#define GS_TEXCUBE(gs_set, gs_binding, gs_name) uniform samplerCube gs_name\n"
    "#define GS_TEX2D_ARRAY(gs_set, gs_binding, gs_name) uniform sampler2DArray gs_name\n"
    "#define GS_PUSH(gs_block) layout(std140) uniform gs_block\n"
    "#define GS_IN(gs_loc, gs_type, gs_name) layout(location = gs_loc) in gs_type gs_name\n"
    "#define GS_OUT(gs_loc, gs_type, gs_name) layout(location = gs_loc) out gs_type gs_name\n"
    "#endif\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Shared constants (mirrored in C++: renderer/render_ubo.hpp)\n"
    "//----------------------------------------------------------------------\n"
    "#define GS_MAX_LIGHTS 8\n"
    "#define GS_LIGHT_DIRECTIONAL 0\n"
    "#define GS_LIGHT_POINT 1\n"
    "#define GS_LIGHT_SPOT 2\n"
    "\n"
    "#define GS_ALPHA_OPAQUE 0\n"
    "#define GS_ALPHA_MASK 1\n"
    "#define GS_ALPHA_BLEND 2\n"
    "\n"
    "// Material \"texture present\" bitmask (MaterialUBO.texture_mask.x)\n"
    "#define GS_TEX_BASE_COLOR 1\n"
    "#define GS_TEX_METAL_ROUGH 2\n"
    "#define GS_TEX_NORMAL 4\n"
    "#define GS_TEX_OCCLUSION 8\n"
    "#define GS_TEX_EMISSIVE 16\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Small helpers used by several shaders\n"
    "//----------------------------------------------------------------------\n"
    "float gsSaturate(float v) { return clamp(v, 0.0, 1.0); }\n"
    "vec2 gsSaturate(vec2 v) { return clamp(v, vec2(0.0), vec2(1.0)); }\n"
    "vec3 gsSaturate(vec3 v) { return clamp(v, vec3(0.0), vec3(1.0)); }\n"
    "\n"
    "float gsLuminance(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\n"
    "\n"
    "// sRGB -> linear (exact piecewise curve)\n"
    "vec3 gsSrgbToLinear(vec3 c)\n"
    "{\n"
    "    vec3 lo = c / 12.92;\n"
    "    vec3 hi = pow((c + 0.055) / 1.055, vec3(2.4));\n"
    "    return mix(hi, lo, lessThanEqual(c, vec3(0.04045)));\n"
    "}\n"
    "\n"
    "// linear -> sRGB\n"
    "vec3 gsLinearToSrgb(vec3 c)\n"
    "{\n"
    "    vec3 lo = c * 12.92;\n"
    "    vec3 hi = 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055;\n"
    "    return mix(hi, lo, lessThanEqual(c, vec3(0.0031308)));\n"
    "}\n"
    "\n"
    "// Equirectangular UV <-> direction.\n"
    "// Convention (matches scripts/gen_assets.py):\n"
    "//   u = atan2(dir.z, dir.x) / (2*PI) + 0.5\n"
    "//   v = acos(dir.y) / PI\n"
    "vec2 gsDirectionToEquirectUV(vec3 dir)\n"
    "{\n"
    "    vec3 d = normalize(dir);\n"
    "    float u = atan(d.z, d.x) / (2.0 * 3.14159265358979323846) + 0.5;\n"
    "    float v = acos(clamp(d.y, -1.0, 1.0)) / 3.14159265358979323846;\n"
    "    return vec2(u, v);\n"
    "}\n"
    "\n"
    "vec3 gsEquirectUVToDirection(vec2 uv)\n"
    "{\n"
    "    float phi = (uv.x - 0.5) * 2.0 * 3.14159265358979323846;\n"
    "    float theta = uv.y * 3.14159265358979323846;\n"
    "    return vec3(cos(phi) * sin(theta), cos(theta), sin(phi) * sin(theta));\n"
    "}\n"
    "\n"
    "// Cubemap face directions used by the IBL baker.  Order matches the engine's\n"
    "// layer order: +X, -X, +Y, -Y, +Z, -Z.\n"
    "vec3 gsCubeFaceDirection(int face, vec2 uv)\n"
    "{\n"
    "    // uv in [0,1]^2 with (0,0) at the top-left of the rendered quad.\n"
    "    vec2 t = uv * 2.0 - 1.0; // -> [-1,1], y up after the flip below\n"
    "    t.y = -t.y;\n"
    "    if (face == 0) return normalize(vec3(1.0, t.y, -t.x));   // +X\n"
    "    if (face == 1) return normalize(vec3(-1.0, t.y, t.x));   // -X\n"
    "    if (face == 2) return normalize(vec3(t.x, 1.0, t.y));    // +Y\n"
    "    if (face == 3) return normalize(vec3(t.x, -1.0, -t.y));  // -Y\n"
    "    if (face == 4) return normalize(vec3(t.x, t.y, 1.0));    // +Z\n"
    "    return normalize(vec3(-t.x, t.y, -1.0));                 // -Z\n"
    "}\n"
    "\n"
    "#endif // GENESIS_SHADER_COMMON_H\n"
    "\n"
    "// ---- end #include \"common/genesis_shader.h\" ----\n"
    "// ---- begin common/ubo_layout.h ----\n"
    "/*\n"
    " * Genesis Render - uniform block layouts shared by every shader stage.\n"
    " *\n"
    " * !!! These layouts are mirrored byte-for-byte in C++ !!!\n"
    " *     src/genesis/renderer/render_ubo.hpp\n"
    " * Any change here must be reflected there (and vice versa).\n"
    " *\n"
    " * std140 rules used: only mat4, vec4 and float arrays appear, so the C++ side\n"
    " * can use plain structs with alignas(16) and no padding surprises.\n"
    " */\n"
    "#ifndef GENESIS_UBO_LAYOUT_H\n"
    "#define GENESIS_UBO_LAYOUT_H\n"
    "\n"
    "// ---- begin common/genesis_shader.h ----\n"
    "\n"
    "// ---- end #include \"common/genesis_shader.h\" ----\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// set 0 / binding 0 - per frame (scene) data\n"
    "//----------------------------------------------------------------------\n"
    "GS_UBO(0, 0, PerFrame)\n"
    "{\n"
    "    mat4 u_view;\n"
    "    mat4 u_projection;\n"
    "    mat4 u_view_projection;\n"
    "    mat4 u_inv_view_projection;\n"
    "    mat4 u_inv_view;\n"
    "    vec4 u_camera_position;  // xyz = world space eye, w = vertical fov (radians)\n"
    "    vec4 u_frame_params;     // x = time (s), y = delta time (s), z = frame index, w = exposure\n"
    "    vec4 u_viewport_params;  // x = width, y = height, z = 1/width, w = 1/height\n"
    "    vec4 u_backend_params;   // x = flip uv.y (GL offscreen targets), y = depth [0,1] (1) or [-1,1] (0),\n"
    "                             // z = flip clip y (Vulkan), w = unused\n"
    "};\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// set 0 / binding 1 - light array\n"
    "//----------------------------------------------------------------------\n"
    "struct GpuLight\n"
    "{\n"
    "    vec4 position_range;   // xyz = world position, w = range (point/spot)\n"
    "    vec4 direction_cone;   // xyz = world direction (normalised), w = unused\n"
    "    vec4 color_intensity;  // rgb = linear colour, w = intensity\n"
    "    vec4 type_params;      // x = type (0 dir, 1 point, 2 spot), y = cos(inner),\n"
    "                           // z = cos(outer), w = enabled (0/1)\n"
    "};\n"
    "\n"
    "GS_UBO(0, 1, Lights)\n"
    "{\n"
    "    GpuLight u_lights[GS_MAX_LIGHTS];\n"
    "    vec4 u_light_count_params;  // x = number of active lights, yzw = unused\n"
    "    vec4 u_ambient_color;       // rgb = linear ambient, w = ambient intensity\n"
    "};\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// set 0 / binding 2 - environment / IBL parameters\n"
    "//----------------------------------------------------------------------\n"
    "GS_UBO(0, 2, Environment)\n"
    "{\n"
    "    vec4 u_env_params;    // x = env intensity, y = cos(rotation), z = sin(rotation), w = show skybox\n"
    "    vec4 u_ibl_params;    // x = use IBL (0/1), y = prefilter mip count, z = max lod, w = unused\n"
    "    vec4 u_sky_tint;      // procedural fallback sky colour (top)\n"
    "    vec4 u_ground_tint;   // procedural fallback ground colour (bottom)\n"
    "};\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// set 1 / binding 0 - material\n"
    "//----------------------------------------------------------------------\n"
    "GS_UBO(1, 0, Material)\n"
    "{\n"
    "    vec4 u_base_color_factor;   // rgba, linear (already converted on the CPU)\n"
    "    vec4 u_emissive_factor;     // rgb linear, a = emissive strength\n"
    "    vec4 u_material_params0;    // x = metallic, y = roughness, z = normal scale, w = occlusion strength\n"
    "    vec4 u_material_params1;    // x = alpha cutoff, y = alpha mode, z = double sided, w = unused\n"
    "    vec4 u_texture_mask;        // x = base colour, y = metallic-roughness, z = normal, w = occlusion (0/1)\n"
    "    vec4 u_material_extra;      // x = emissive texture (0/1), y = uv scale x, z = uv scale y, w = unused\n"
    "};\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// set 2 / binding 0 - per draw (dynamic offset)\n"
    "//----------------------------------------------------------------------\n"
    "GS_UBO(2, 0, PerDraw)\n"
    "{\n"
    "    mat4 u_model;\n"
    "    mat4 u_normal_matrix;   // transpose(inverse(model)) upper 3x3\n"
    "    vec4 u_object_params;   // x = pick id, y = wireframe (0/1), z = uv offset x, w = uv offset y\n"
    "};\n"
    "\n"
    "#endif // GENESIS_UBO_LAYOUT_H\n"
    "\n"
    "// ---- end #include \"common/ubo_layout.h\" ----\n"
    "// ---- begin common/pbr.h ----\n"
    "/*\n"
    " * Genesis Render - PBR shading library (shared by mesh / IBL shaders)\n"
    " *\n"
    " * Two direct-light BRDF models are available, selected at runtime by\n"
    " * `u_material_extra`/engine shading mode so that the classic Blinn-Phong\n"
    " * decomposition (diffuse + specular + Fresnel + metallic) can be compared\n"
    " * against the Cook-Torrance GGX model:\n"
    " *\n"
    " *   GS_SHADING_COOK_TORRANCE : D = GGX/Trowbridge-Reitz\n"
    " *                              G = Smith-Schlick-GGX\n"
    " *                              F = Schlick\n"
    " *   GS_SHADING_BLINN_PHONG   : D = Blinn-Phong lobe ((n+1)/2pi * (N.H)^n)\n"
    " *                              G = Smith-Schlick-GGX (keeps energy sane)\n"
    " *                              F = Schlick\n"
    " *\n"
    " * Both use the metallic-roughness workflow:\n"
    " *   F0 = mix(vec3(0.04), albedo, metallic)\n"
    " *   kD = (1 - F) * (1 - metallic)\n"
    " *\n"
    " * Indirect light is the standard split-sum approximation:\n"
    " *   Li = kD * irradiance(N) * albedo + prefiltered(R, roughness) * (F * brdf.x + brdf.y)\n"
    " * exactly like Piccolo's mesh_lighting.inl, so results can be compared\n"
    " * 1:1 between the two engines.\n"
    " */\n"
    "#ifndef GENESIS_PBR_H\n"
    "#define GENESIS_PBR_H\n"
    "\n"
    "// ---- begin common/genesis_shader.h ----\n"
    "\n"
    "// ---- end #include \"common/genesis_shader.h\" ----\n"
    "\n"
    "#define GS_SHADING_COOK_TORRANCE 0\n"
    "#define GS_SHADING_BLINN_PHONG 1\n"
    "\n"
    "const float GS_PI = 3.14159265358979323846;\n"
    "const float GS_MIN_ROUGHNESS = 0.045; // keeps D/G finite (Piccolo clamps to 0.05)\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Surface description handed to the light evaluators\n"
    "//----------------------------------------------------------------------\n"
    "struct PbrSurface\n"
    "{\n"
    "    vec3 N;          // world space normal\n"
    "    vec3 V;          // world space view direction (surface -> eye)\n"
    "    vec3 albedo;     // linear diffuse reflectance\n"
    "    float metallic;  // 0..1\n"
    "    float roughness; // 0..1 (perceptual, squared internally)\n"
    "    float ao;        // 0..1 occlusion\n"
    "    vec3 F0;         // normal-incidence reflectance\n"
    "    vec3 emissive;   // linear emissive radiance\n"
    "    int shading_mode;\n"
    "};\n"
    "\n"
    "PbrSurface gsMakeSurface(vec3 N, vec3 V, vec3 albedo, float metallic, float roughness,\n"
    "                         float ao, vec3 emissive, int shading_mode)\n"
    "{\n"
    "    PbrSurface s;\n"
    "    s.N = normalize(N);\n"
    "    s.V = normalize(V);\n"
    "    s.albedo = albedo;\n"
    "    s.metallic = gsSaturate(metallic);\n"
    "    s.roughness = max(gsSaturate(roughness), GS_MIN_ROUGHNESS);\n"
    "    s.ao = gsSaturate(ao);\n"
    "    s.emissive = emissive;\n"
    "    s.shading_mode = shading_mode;\n"
    "    s.F0 = mix(vec3(0.04), albedo, s.metallic);\n"
    "    return s;\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Normal distribution functions\n"
    "//----------------------------------------------------------------------\n"
    "float gsDistributionGGX(float NoH, float roughness)\n"
    "{\n"
    "    float a = roughness * roughness;\n"
    "    float a2 = a * a;\n"
    "    float d = (NoH * a2 - NoH) * NoH + 1.0;\n"
    "    return a2 / max(GS_PI * d * d, 1e-7);\n"
    "}\n"
    "\n"
    "// Blinn-Phong lobe, normalised so that it integrates to 1 over the hemisphere.\n"
    "// shininess is derived from the perceptual roughness: n = 2/a^2 - 2\n"
    "float gsDistributionBlinnPhong(float NoH, float roughness)\n"
    "{\n"
    "    float a = max(roughness * roughness, 1e-4);\n"
    "    float shininess = max(2.0 / (a * a) - 2.0, 1.0);\n"
    "    float norm = (shininess + 2.0) / (2.0 * GS_PI);\n"
    "    return norm * pow(max(NoH, 0.0), shininess);\n"
    "}\n"
    "\n"
    "float gsDistribution(float NoH, float roughness, int shading_mode)\n"
    "{\n"
    "    if (shading_mode == GS_SHADING_BLINN_PHONG)\n"
    "        return gsDistributionBlinnPhong(NoH, roughness);\n"
    "    return gsDistributionGGX(NoH, roughness);\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Geometry / visibility\n"
    "//----------------------------------------------------------------------\n"
    "float gsGeometrySchlickGGX(float NoV, float roughness)\n"
    "{\n"
    "    // Direct lighting uses k = (r+1)^2 / 8 (the Schlick-GGX approximation).\n"
    "    float k = (roughness + 1.0) * (roughness + 1.0) / 8.0;\n"
    "    return NoV / (NoV * (1.0 - k) + k);\n"
    "}\n"
    "\n"
    "float gsGeometrySmith(float NoV, float NoL, float roughness)\n"
    "{\n"
    "    return gsGeometrySchlickGGX(NoV, roughness) * gsGeometrySchlickGGX(NoL, roughness);\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Fresnel\n"
    "//----------------------------------------------------------------------\n"
    "vec3 gsFresnelSchlick(float cosTheta, vec3 F0)\n"
    "{\n"
    "    float f = pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0);\n"
    "    return F0 + (vec3(1.0) - F0) * f;\n"
    "}\n"
    "\n"
    "// Roughness aware variant used for the IBL specular term.\n"
    "vec3 gsFresnelSchlickRough(float cosTheta, vec3 F0, float roughness)\n"
    "{\n"
    "    vec3 one = max(vec3(1.0 - roughness), F0);\n"
    "    float f = pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0);\n"
    "    return F0 + (one - F0) * f;\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Analytic environment BRDF approximation (Karalis), used when no BRDF LUT\n"
    "// is bound (and as a cross-check for the baked LUT in the test suite).\n"
    "//----------------------------------------------------------------------\n"
    "vec2 gsEnvBRDFApprox(float NoV, float roughness)\n"
    "{\n"
    "    const vec4 c0 = vec4(-1.0, -0.0275, -0.572, 0.022);\n"
    "    const vec4 c1 = vec4(1.0, 0.0425, 1.04, -0.04);\n"
    "    vec4 r = roughness * c0 + c1;\n"
    "    float a004 = min(r.x * r.x, exp2(-9.28 * NoV)) * r.x + r.y;\n"
    "    vec2 ab = vec2(-1.04, 1.04) * a004 + r.zw;\n"
    "    return gsSaturate(ab);\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Direct light evaluation\n"
    "//\n"
    "// `radiance` is the incident light radiance already attenuated by distance /\n"
    "// spot cone / NdotL-free geometry (the caller multiplies by NoL).\n"
    "//----------------------------------------------------------------------\n"
    "vec3 gsEvaluateDirectLight(PbrSurface s, vec3 L, vec3 radiance)\n"
    "{\n"
    "    vec3 Lv = normalize(L);\n"
    "    vec3 H = normalize(s.V + Lv);\n"
    "\n"
    "    float NoV = max(dot(s.N, s.V), 1e-5);\n"
    "    float NoL = max(dot(s.N, Lv), 0.0);\n"
    "    float NoH = max(dot(s.N, H), 0.0);\n"
    "    float VoH = max(dot(s.V, H), 0.0);\n"
    "\n"
    "    if (NoL <= 0.0)\n"
    "        return vec3(0.0);\n"
    "\n"
    "    float D = gsDistribution(NoH, s.roughness, s.shading_mode);\n"
    "    float G = gsGeometrySmith(NoV, NoL, s.roughness);\n"
    "    vec3 F = gsFresnelSchlick(VoH, s.F0);\n"
    "\n"
    "    vec3 specular = (D * G * F) / max(4.0 * NoV * NoL, 1e-4);\n"
    "\n"
    "    // Energy conservation: what is not reflected specularly is diffuse, and\n"
    "    // metals have no diffuse response.\n"
    "    vec3 kS = F;\n"
    "    vec3 kD = (vec3(1.0) - kS) * (1.0 - s.metallic);\n"
    "    vec3 diffuse = kD * s.albedo / GS_PI;\n"
    "\n"
    "    return (diffuse + specular) * radiance * NoL;\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Indirect light (split sum approximation)\n"
    "//\n"
    "//   irradiance   : cosine weighted convolution of the environment, sampled\n"
    "//                  with N\n"
    "//   prefiltered  : GGX convolution of the environment, sampled with R at a\n"
    "//                  mip level derived from the roughness\n"
    "//   brdf         : (scale, bias) from the BRDF integration LUT\n"
    "//----------------------------------------------------------------------\n"
    "vec3 gsEvaluateIBL(PbrSurface s, vec3 irradiance, vec3 prefiltered, vec2 brdf)\n"
    "{\n"
    "    float NoV = max(dot(s.N, s.V), 1e-5);\n"
    "    vec3 F = gsFresnelSchlickRough(NoV, s.F0, s.roughness);\n"
    "    vec3 kS = F;\n"
    "    vec3 kD = (vec3(1.0) - kS) * (1.0 - s.metallic);\n"
    "\n"
    "    vec3 diffuse = kD * irradiance * s.albedo;\n"
    "    vec3 specular = prefiltered * (F * brdf.x + brdf.y);\n"
    "\n"
    "    return (diffuse + specular) * s.ao;\n"
    "}\n"
    "\n"
    "// Convenience overload used when only a BRDF approximation is available.\n"
    "vec3 gsEvaluateIBLApprox(PbrSurface s, vec3 irradiance, vec3 prefiltered)\n"
    "{\n"
    "    float NoV = max(dot(s.N, s.V), 1e-5);\n"
    "    return gsEvaluateIBL(s, irradiance, prefiltered, gsEnvBRDFApprox(NoV, s.roughness));\n"
    "}\n"
    "\n"
    "//----------------------------------------------------------------------\n"
    "// Light attenuation helpers (shared by the mesh shader)\n"
    "//----------------------------------------------------------------------\n"
    "float gsDistanceAttenuation(float distance, float range)\n"
    "{\n"
    "    if (range <= 0.0)\n"
    "        return 1.0;\n"
    "    // Unreal style smooth windowed inverse square falloff.\n"
    "    float d = max(distance, 1e-4);\n"
    "    float window = gsSaturate(1.0 - pow(d / range, 4.0));\n"
    "    return (window * window) / (d * d);\n"
    "}\n"
    "\n"
    "float gsSpotAttenuation(vec3 light_dir, vec3 to_fragment, float cos_inner, float cos_outer)\n"
    "{\n"
    "    float cos_angle = dot(normalize(-light_dir), normalize(-to_fragment));\n"
    "    if (cos_outer >= cos_inner)\n"
    "        return gsSaturate(cos_angle);\n"
    "    return gsSaturate((cos_angle - cos_outer) / max(cos_inner - cos_outer, 1e-5));\n"
    "}\n"
    "\n"
    "#endif // GENESIS_PBR_H\n"
    "\n"
    "// ---- end #include \"common/pbr.h\" ----\n"
    "\n"
    "GS_IN(0, vec2, v_uv);\n"
    "GS_OUT(0, vec4, out_color);\n"
    "\n"
    "// Skybox specific bindings (this pipeline uses its own small layout):\n"
    "//   set 0 binding 1 : sampler2D  u_sky_equirect\n"
    "//   set 0 binding 2 : samplerCube u_sky_cube\n"
    "GS_TEX2D(0, 1, u_sky_equirect);\n"
    "GS_TEXCUBE(0, 2, u_sky_cube);\n"
    "\n"
    "void main()\n"
    "{\n"
    "    // Reconstruct the view ray for this pixel at the far plane.\n"
    "    // v_uv has its origin at the top-left, which corresponds to NDC (-1,-1)\n"
    "    // on both backends (row 0 of the render target).\n"
    "    vec3 ndc = vec3(v_uv.x * 2.0 - 1.0, v_uv.y * 2.0 - 1.0, 1.0);\n"
    "    vec4 world = u_inv_view_projection * vec4(ndc, 1.0);\n"
    "    vec3 dir = normalize(world.xyz / max(abs(world.w), 1e-6) - u_camera_position.xyz);\n"
    "\n"
    "    // Apply the environment rotation so that the sun can be moved at runtime.\n"
    "    vec2 rot = u_env_params.yz;\n"
    "    vec3 rotated = vec3(rot.x * dir.x + rot.y * dir.z, dir.y, -rot.y * dir.x + rot.x * dir.z);\n"
    "\n"
    "    vec3 color;\n"
    "    int mode = int(u_ibl_params.z + 0.5);\n"
    "    if (mode == 1)\n"
    "    {\n"
    "        vec2 uv = gsDirectionToEquirectUV(rotated);\n"
    "        color = texture(u_sky_equirect, uv).rgb;\n"
    "    }\n"
    "    else if (mode == 2)\n"
    "    {\n"
    "        color = textureLod(u_sky_cube, rotated, 0.0).rgb;\n"
    "    }\n"
    "    else\n"
    "    {\n"
    "        float t = gsSaturate(rotated.y * 0.5 + 0.5);\n"
    "        color = mix(u_ground_tint.rgb, u_sky_tint.rgb, t);\n"
    "        vec3 sun_dir = normalize(vec3(0.4, 0.6, 0.3));\n"
    "        float sun = pow(gsSaturate(dot(rotated, sun_dir)), 512.0);\n"
    "        float glow = pow(gsSaturate(dot(rotated, sun_dir)), 8.0);\n"
    "        color += vec3(1.0, 0.9, 0.7) * sun * 60.0 + vec3(0.4, 0.35, 0.3) * glow * 0.5;\n"
    "    }\n"
    "\n"
    "    out_color = vec4(max(color * u_env_params.x, vec3(0.0)), 1.0);\n"
    "    // Force the fragment to the far plane so that geometry always wins.\n"
    "    gl_FragDepth = 1.0;\n"
    "}\n"
    "";
