size_t shaderCount()
{
    return sizeof(k_shaders) / sizeof(k_shaders[0]);
}

const ShaderBinary *findShader(const char *name)
{
    if (!name) return nullptr;
    for (const ShaderBinary &s : k_shaders)
        if (std::strcmp(s.name, name) == 0) return &s;
    return nullptr;
}

